# Generated by Phase: IMPLEMENT | Feature: EVOL-051
"""Governance digest currency of the feature's planning artefacts (EVOL-051) — the loop checks what the push checks.

For the feature the branch names (`feature/{ID}…`, `epic/{ID}…` — the branch grammar of the currency gate; a
`fix/` or `hotfix/` branch names no feature and is not judged), every planning artefact listed in
`verification.digest_artefacts` that exists under `docs/spec/{ID}/` (`design.md` by default — the technical
artefact BLUEPRINT § GCD writes; a project lists `dev_plan.md` once IMPLEMENT --plan writes its § Governance; the
journey is business-pure, LAW-16, and carries no digest) is judged on two predicates:

  fingerprint   frontmatter `governance_digest_version` equals the current governance fingerprint — the snapshot's
                `constitution_hash[:8]`, the GCRP identity BLUEPRINT writes into design.md and IMPLEMENT Step 0b
                reads. At `ci` the snapshot is not on the runner (`.context/` is not tracked): n/a, completeness only.
  completeness  the artefact REFERENCES every rule the corpus binds to this change — `rules/<stem>.md` or `<stem>.md`,
                in the body after the frontmatter, outside code fences (a bare word is never a reference: `testing`
                in a sentence proves nothing). The change is the tree on disk against the merge-base with the diff
                base — committed or not, the static round runs before the commit; an empty change binds the always-on
                rules only, never the whole tree.

Absent, stale or incomplete → red, in the static round before the critics and at the push (a profile member) — one
predicate, never a copy. No feature on the branch, or no artefact yet → ok with the reason. Governance not
delivered (the snapshot, the config) is RED with the reason, never a fault the push walks past.
"""
from __future__ import annotations

import re
from pathlib import Path

from . import corpus
from .coherence import FEATURE_IN_BRANCH
from .common import GateFault, context, read_frontmatter
from .seal import _base_of, _delta, _reference, current_branch, tree_entries, vcfg

SNAPSHOT = ".context/governance_snapshot.md"
DIGEST_KEY = "governance_digest_version"
FENCE = re.compile(r"^(```|~~~).*?^\1[ \t]*$", re.M | re.S)
FM = re.compile(r"^---\n.*?\n---\n", re.S)


def feature_id(branch: str) -> str | None:
    m = FEATURE_IN_BRANCH.match(branch or "")
    return m.group(1) if m else None


def fingerprint(repo: Path) -> str | None:
    """constitution_hash[:8] of the governance snapshot; None in the framework repo (no constitution).
    Raises GateFault downstream when the snapshot is missing or carries no hash."""
    p = repo / SNAPSHOT
    if not p.is_file():
        if context(repo) == "meta":
            return None
        raise GateFault(f"{SNAPSHOT} is missing — the governance snapshot is the GCRP identity every digest is checked against (SETUP materialises it; validate-governance.sh regenerates it)")
    fm = read_frontmatter(p)
    h = str(fm.get("constitution_hash") or "").strip()
    if not h or h.lower() in ("null", "none"):
        if context(repo) == "meta":
            return None
        raise GateFault(f"{SNAPSHOT} carries no constitution_hash — regenerate the snapshot")
    return h[:8]


def changed_paths(repo: Path, base: str, cfg: dict | None = None) -> list[str]:
    """The change as it stands: the tree on disk (tracked + untracked) against the merge-base with the diff base."""
    cfg = cfg or vcfg(repo)
    return _delta(tree_entries(repo, skip=cfg["dir"]), tree_entries(repo, _reference(repo, base), skip=cfg["dir"]))


def bound_rules(repo: Path, base: str, cfg: dict | None = None) -> list[str]:
    """The rule names (file stems) the corpus binds to the change: always-on, and path-bound to a changed path.
    An empty change binds the always-on rules only."""
    paths = changed_paths(repo, base, cfg)
    uni = corpus.universe(repo)
    out = set()
    for r in uni["rules"]:
        if r.get("error"):
            continue
        if corpus.matches(r["applicable_when"], {}, paths)[0]:
            out.add(Path(r["path"]).stem)
    return sorted(out)


def references(text: str) -> set[str]:
    """The rule stems the artefact references: `rules/<stem>.md` or `<stem>.md` in the body, outside code fences."""
    body = FM.sub("", text, count=1)
    body = FENCE.sub("", body)
    return {m.group(1) for m in re.finditer(r"(?<![\w/.-])(?:rules/)?([\w.-]+?)\.md(?![\w-])", body)}


def check(repo: Path, base: str, branch: str | None = None, control_point: str = "push") -> dict:
    branch = branch or current_branch(repo)
    fid = feature_id(branch)
    if not fid:
        return {"ok": True, "feature": None, "artefacts": [], "reason": f"`{branch or 'detached'}` names no feature — no planning artefact to judge"}
    try:
        cfg = vcfg(repo)
    except GateFault as e:
        return {"ok": False, "feature": fid, "artefacts": [], "reason": str(e)}
    folder = repo / "docs/spec" / fid
    present = [a for a in cfg["digest_artefacts"] if (folder / a).is_file()]
    if not present:
        return {"ok": True, "feature": fid, "artefacts": [], "reason": f"docs/spec/{fid}/ carries none of {', '.join(cfg['digest_artefacts'])} yet — nothing to judge"}
    fp_error = None
    if control_point == "ci":
        fp = None
    else:
        try:
            fp = fingerprint(repo)
        except GateFault as e:
            fp, fp_error = None, str(e)
    rules = bound_rules(repo, base, cfg)
    rows, red = [], []
    for a in present:
        p = folder / a
        rel = f"docs/spec/{fid}/{a}"
        try:
            fm = read_frontmatter(p)
        except GateFault as e:
            rows.append({"artefact": rel, "ok": False, "reason": f"unreadable frontmatter: {e}"}); red.append(rel); continue
        have = str(fm.get(DIGEST_KEY) or "").strip()
        text = p.read_text(encoding="utf-8", errors="replace")
        problems = []
        if not have:
            problems.append(f"no `{DIGEST_KEY}` in the frontmatter — the digest was never generated (BLUEPRINT § GCD writes it; IMPLEMENT --plan copies it into dev_plan.md)")
        elif fp_error:
            problems.append(f"fingerprint unverifiable: {fp_error}")
        elif fp is not None and have[:8] != fp:
            problems.append(f"stale: digest {have[:8]}, corpus {fp} — regenerate (BLUEPRINT --refine {fid})")
        refs = references(text)
        missing = [r for r in rules if r not in refs]
        if missing:
            problems.append(f"incomplete: bound rule(s) never referenced as rules/<name>.md — {', '.join(missing)}")
        rows.append({"artefact": rel, "ok": not problems, "reason": "; ".join(problems) or "current and complete"})
        if problems:
            red.append(rel)
    note = " (fingerprint n/a at ci: the snapshot is not on the runner)" if control_point == "ci" else ""
    return {"ok": not red, "feature": fid, "fingerprint": fp, "bound": rules, "artefacts": rows,
            "reason": (f"{len(red)} of {len(rows)} planning artefact(s) stale or incomplete" if red else f"{len(rows)} planning artefact(s) current and complete") + note}


def render(res: dict) -> str:
    if res["ok"] and not res.get("artefacts"):
        return f"digests: ok — {res['reason']}"
    if not res["ok"] and not res.get("artefacts"):
        return f"digests: RED — {res['reason']}"
    lines = [f"digests: {'ok' if res['ok'] else 'RED'} — {res['reason']} (feature {res['feature']}, corpus {res.get('fingerprint') or '—'})"]
    for r in res.get("artefacts", []):
        lines.append(f"  {'✓' if r['ok'] else '✗'} {r['artefact']}: {r['reason']}")
    return "\n".join(lines)
